def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def step_toward(a, b):
        return clamp_step(b - a)

    def safe_pos(x, default=(0, 0)):
        try:
            if isinstance(x, (list, tuple)) and len(x) >= 2:
                return int(x[0]), int(x[1])
        except Exception:
            pass
        return default

    def first_pos(items):
        if not items:
            return None
        for it in items:
            p = safe_pos(it, None)
            if p is not None:
                return p
        return None

    def best_by(items, score_fn):
        best_item = None
        best_score = None
        for it in items or []:
            try:
                sc = score_fn(it)
            except Exception:
                continue
            if best_item is None or sc < best_score:
                best_item = it
                best_score = sc
        return best_item

    env = observation.get("environment_name", "")
    sx, sy = safe_pos(observation.get("self_position", (0, 0)))
    ox, oy = safe_pos(observation.get("opponent_position", (sx, sy)))

    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return [step_toward(sx, ox), step_toward(sy, oy)]
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = best_by(corners, lambda c: -(abs(c[0] - ox) + abs(c[1] - oy)))
        if target is None:
            return [0, 0]
        return [step_toward(sx, target[0]), step_toward(sy, target[1])]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("neutral_cells") or []
        target = best_by(targets, lambda c: abs(c[0] - sx) + abs(c[1] - sy))
